assert len(rows)==len(checks)==31
with (r/'findings.csv').open('w',newline='') as f:
 writer=csv.writer(f)
 writer.writerow(['Request','Item','Their answer','Your answer','Your source','Verdict','Evidence'])
 for row,(answer,source,evidence) in zip(rows,checks):
  writer.writerow([row['Request'],row['Item'],row['Answer'],answer,source,'agree',evidence])
print('Wrote 31 findings: agree=31, disagree=0, missing=0.')
